#include "parser.hpp"
#include <sstream>
namespace g2m {
Parser::Parser(const std::vector<Token>&t):tokens_(t){}
const Token&Parser::peek()const{return tokens_[current_];}const Token&Parser::previous()const{return tokens_[current_-1];}
bool Parser::check(TokenKind k)const{return peek().kind==k;}bool Parser::match(TokenKind k){if(!check(k))return false;++current_;return true;}
const Token&Parser::consume(TokenKind k,const std::string&m){if(check(k))return tokens_[current_++];error(peek(),m);return peek();}
void Parser::error(const Token&t,const std::string&m){errors_.push_back("line "+std::to_string(t.line)+":"+std::to_string(t.column)+": "+m);}
std::string Parser::parseModulePath(){auto p=consume(TokenKind::Identifier,"expected module name").lexeme;while(match(TokenKind::ColonColon))p+="::"+consume(TokenKind::Identifier,"expected path component").lexeme;return p;}
std::string Parser::parseType(){Token t=peek();switch(t.kind){case TokenKind::KwI8:case TokenKind::KwI16:case TokenKind::KwI32:case TokenKind::KwI64:case TokenKind::KwI128:case TokenKind::KwU8:case TokenKind::KwU16:case TokenKind::KwU32:case TokenKind::KwU64:case TokenKind::KwU128:case TokenKind::KwIsize:case TokenKind::KwUsize:case TokenKind::KwInt:case TokenKind::KwF32:case TokenKind::KwF64:case TokenKind::KwBool:case TokenKind::KwChar:case TokenKind::KwString:case TokenKind::KwNil:case TokenKind::Identifier:++current_;return t.lexeme;default:error(t,"expected type name");return "i32";}}
std::string Parser::parseExpression(const std::vector<TokenKind>&stops){std::ostringstream o;int par=0,br=0,sq=0;bool any=false;while(!check(TokenKind::EndOfFile)){auto k=peek().kind;if(par==0&&br==0&&sq==0){bool stop=false;for(auto x:stops)if(k==x)stop=true;if(stop)break;}Token t=tokens_[current_++];if(t.kind==TokenKind::LeftParen)++par;if(t.kind==TokenKind::RightParen)--par;if(t.kind==TokenKind::LeftBrace)++br;if(t.kind==TokenKind::RightBrace){if(br==0)break;--br;}if(t.kind==TokenKind::LeftBracket)++sq;if(t.kind==TokenKind::RightBracket)--sq;
 if(any){auto prev=tokens_[current_-2].kind;bool tight=(k==TokenKind::RightParen||k==TokenKind::RightBracket||k==TokenKind::Comma||k==TokenKind::Semicolon||prev==TokenKind::LeftParen||prev==TokenKind::LeftBracket||prev==TokenKind::ColonColon);if(!tight)o<<' ';}o<<t.lexeme;any=true;}return o.str();}
Function Parser::parseFunction(){consume(TokenKind::KwFn,"expected fn");Function f;f.name=consume(TokenKind::Identifier,"expected function name").lexeme;consume(TokenKind::LeftParen,"expected '('");if(!check(TokenKind::RightParen)){do{Parameter p;p.type=parseType();if(match(TokenKind::Ellipsis))p.variadic=true;p.name=consume(TokenKind::Identifier,"expected parameter name").lexeme;f.parameters.push_back(p);}while(match(TokenKind::Comma));}consume(TokenKind::RightParen,"expected ')'");f.returnType=parseType();if(match(TokenKind::Semicolon)){f.declarationOnly=true;return f;}consume(TokenKind::LeftBrace,"expected function body");while(!check(TokenKind::RightBrace)&&!check(TokenKind::EndOfFile))f.body.push_back(parseStatement());consume(TokenKind::RightBrace,"expected '}'");return f;}
Statement Parser::parseStatement(){Statement s;
 if(match(TokenKind::LeftBrace)){s.kind=Statement::Kind::Block;while(!check(TokenKind::RightBrace)&&!check(TokenKind::EndOfFile))s.body.push_back(parseStatement());consume(TokenKind::RightBrace,"expected '}'");return s;}
 if(match(TokenKind::KwIf)){s.kind=Statement::Kind::If;consume(TokenKind::LeftParen,"expected '(' after if");s.condition=parseExpression({TokenKind::RightParen});consume(TokenKind::RightParen,"expected ')'");Statement b=parseStatement();if(b.kind==Statement::Kind::Block)s.body=std::move(b.body);else s.body.push_back(std::move(b));if(match(TokenKind::KwElse)){Statement e=parseStatement();if(e.kind==Statement::Kind::Block)s.otherwise=std::move(e.body);else s.otherwise.push_back(std::move(e));}return s;}
 if(match(TokenKind::KwWhile)){s.kind=Statement::Kind::While;consume(TokenKind::LeftParen,"expected '(' after while");s.condition=parseExpression({TokenKind::RightParen});consume(TokenKind::RightParen,"expected ')'");Statement b=parseStatement();if(b.kind==Statement::Kind::Block)s.body=std::move(b.body);else s.body.push_back(std::move(b));return s;}
 if(match(TokenKind::KwFor)){s.kind=Statement::Kind::For;consume(TokenKind::LeftParen,"expected '(' after for");s.name=parseExpression({TokenKind::Semicolon});consume(TokenKind::Semicolon,"expected ';' in for");s.condition=parseExpression({TokenKind::Semicolon});consume(TokenKind::Semicolon,"expected ';' in for");s.increment=parseExpression({TokenKind::RightParen});consume(TokenKind::RightParen,"expected ')'");Statement b=parseStatement();if(b.kind==Statement::Kind::Block)s.body=std::move(b.body);else s.body.push_back(std::move(b));return s;}
 if(match(TokenKind::KwBreak)){s.kind=Statement::Kind::Break;consume(TokenKind::Semicolon,"expected ';'");return s;}
 if(match(TokenKind::KwContinue)){s.kind=Statement::Kind::Continue;consume(TokenKind::Semicolon,"expected ';'");return s;}
 if(match(TokenKind::KwReturn)){s.kind=Statement::Kind::Return;if(!check(TokenKind::Semicolon))s.value=parseExpression({TokenKind::Semicolon});consume(TokenKind::Semicolon,"expected ';' after return");return s;}
 bool mut=match(TokenKind::KwMut),cn=false;if(!mut)cn=match(TokenKind::KwConst);
 auto isType=[](TokenKind k){return k>=TokenKind::KwI8&&k<=TokenKind::KwString;};
 if(mut||cn||isType(peek().kind)){s.kind=Statement::Kind::Variable;s.mutableValue=mut;s.constant=cn;s.declaredType=parseType();s.name=consume(TokenKind::Identifier,"expected variable name").lexeme;consume(TokenKind::Equal,"expected '='");s.value=parseExpression({TokenKind::Semicolon});consume(TokenKind::Semicolon,"expected ';'");return s;}
 s.kind=Statement::Kind::Expression;s.value=parseExpression({TokenKind::Semicolon});consume(TokenKind::Semicolon,"expected ';'");if(s.value.empty())error(peek(),"expected expression");return s;
}
Program Parser::parse(){Program p;if(match(TokenKind::KwPub)){consume(TokenKind::KwModule,"expected module");p.modulePublic=true;p.moduleName=parseModulePath();consume(TokenKind::Semicolon,"expected ';'");}else if(match(TokenKind::KwModule)){p.moduleName=parseModulePath();consume(TokenKind::Semicolon,"expected ';'");}
 while(!check(TokenKind::EndOfFile)){if(match(TokenKind::KwImport)){p.imports.push_back(parseModulePath());consume(TokenKind::Semicolon,"expected ';'");}else if(check(TokenKind::KwFn))p.functions.push_back(parseFunction());else{error(peek(),"expected import or function declaration");++current_;}}return p;}
}